from __future__ import annotations

from datetime import datetime, timezone
import json
from pathlib import Path
import re
from typing import Any
from urllib.parse import urlsplit, urlunsplit

import feedparser
import httpx
import yaml

from .paths import repo_root
from .models import ResearchCard


SKIP_TERMS = (
    "biological attack",
    "bioweapon",
    "weaponize",
    "bomb making",
    "guerilla warfare",
    "csam",
)


def _allowed(item: dict) -> bool:
    blob = f"{item.get('title', '')} {item.get('summary', '')}".lower()
    return not any(term in blob for term in SKIP_TERMS)


def _feeds() -> list[dict[str, str]]:
    raw = yaml.safe_load((repo_root() / "config" / "feeds.yaml").read_text(encoding="utf-8"))
    return list(raw.get("feeds") or [])


def _entry_datetime(entry: Any) -> datetime | None:
    parsed = getattr(entry, "published_parsed", None) or getattr(entry, "updated_parsed", None)
    if not parsed:
        return None
    return datetime(*parsed[:6], tzinfo=timezone.utc)


def _canonical_url(value: str) -> str:
    parts = urlsplit(value.strip())
    return urlunsplit((parts.scheme.lower(), parts.netloc.lower(), parts.path.rstrip("/"), parts.query, ""))


def _title_key(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", " ", value.lower()).strip()


def _relevance(title: str, summary: str, topics: list[str]) -> float:
    blob = f"{title} {summary}".lower()
    vocabulary = {
        "agent", "rag", "retrieval", "inference", "model", "llm", "postgres", "pgvector",
        "fastapi", "pydantic", "typescript", "next.js", "security", "evaluation", "structured",
    }
    score = sum(1.0 for term in vocabulary if term in blob)
    score += sum(0.5 for topic in topics if topic.lower() in blob)
    return score


def fetch_feeds(*, limit_per_feed: int = 8, timeout: float = 20.0) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    seen_urls: set[str] = set()
    seen_titles: set[str] = set()
    collected_at = datetime.now(timezone.utc)
    headers = {"User-Agent": "linkedin-operator/0.1 (personal research bot; +https://github.com/rhrits)"}
    with httpx.Client(timeout=timeout, headers=headers, follow_redirects=True) as client:
        for feed in _feeds():
            try:
                response = client.get(feed["url"])
                response.raise_for_status()
            except Exception as exc:
                items.append(
                    {
                        "source": feed["name"],
                        "error": str(exc),
                    }
                )
                continue
            parsed = feedparser.parse(response.content)
            for entry in parsed.entries[:limit_per_feed]:
                link = _canonical_url(getattr(entry, "link", ""))
                title = getattr(entry, "title", "").strip()
                title_key = _title_key(title)
                if not link or not title or link in seen_urls or title_key in seen_titles:
                    continue
                seen_urls.add(link)
                seen_titles.add(title_key)
                topics = list(feed.get("topics") or [])
                item = {
                    "source": feed["name"],
                    "title": title,
                    "link": link,
                    "summary": _strip_html(getattr(entry, "summary", "") or getattr(entry, "description", "")),
                    "published_at": _entry_datetime(entry),
                    "collected_at": collected_at,
                    "source_type": str(feed.get("type") or "technical_article"),
                    "quality_tier": int(feed.get("tier") or 2),
                    "topics": topics,
                }
                item["relevance_score"] = _relevance(title, item["summary"], topics)
                if _allowed(item):
                    items.append(item)
    return items


def save_brief(items: list[dict[str, Any]], dest: Path | None = None) -> Path:
    day = datetime.now(timezone.utc).date().isoformat()
    dest = dest or (repo_root() / "research" / f"{day}.md")
    dest.parent.mkdir(parents=True, exist_ok=True)
    lines = [f"# Research brief {day}", "", "Allowlisted public RSS/Atom only. Never LinkedIn.", ""]
    ok = [i for i in items if i.get("title")]
    errors = [i for i in items if i.get("error")]
    for item in ok:
        lines.append(f"- **{item['source']}**: [{item['title']}]({item['link']})")
        published = item.get("published_at")
        lines.append(
            f"  - Type: {item.get('source_type', 'technical_article')} | "
            f"Tier: {item.get('quality_tier', 2)} | Relevance: {item.get('relevance_score', 0):.1f}"
        )
        if published:
            value = published.isoformat() if isinstance(published, datetime) else str(published)
            lines.append(f"  - Published: {value}")
        if item.get("summary"):
            lines.append(f"  - {item['summary'][:280]}")
    if errors:
        lines.append("")
        lines.append("## Feed errors")
        for item in errors:
            lines.append(f"- {item['source']}: {item['error']}")
    dest.write_text("\n".join(lines) + "\n", encoding="utf-8")
    cards = [
        ResearchCard(
            source=str(item["source"]),
            title=str(item["title"]),
            url=str(item["link"]),
            summary=str(item.get("summary") or ""),
            published_at=item.get("published_at"),
            collected_at=item.get("collected_at") or datetime.now(timezone.utc),
            source_type=str(item.get("source_type") or "technical_article"),
            quality_tier=int(item.get("quality_tier") or 2),
            topics=list(item.get("topics") or []),
            relevance_score=float(item.get("relevance_score") or 0.0),
        )
        for item in ok
    ]
    dest.with_suffix(".json").write_text(
        json.dumps([card.model_dump(mode="json") for card in cards], indent=2) + "\n",
        encoding="utf-8",
    )
    return dest


def load_cards(brief_path: Path | None) -> list[ResearchCard]:
    if not brief_path:
        return []
    sidecar = brief_path.with_suffix(".json")
    if not sidecar.exists():
        return []
    data = json.loads(sidecar.read_text(encoding="utf-8"))
    return [ResearchCard.model_validate(item) for item in data]


def _strip_html(value: str) -> str:
    text = value.replace("<p>", " ").replace("</p>", " ")
    out: list[str] = []
    skip = False
    for ch in text:
        if ch == "<":
            skip = True
            continue
        if ch == ">":
            skip = False
            continue
        if not skip:
            out.append(ch)
    return " ".join("".join(out).split())
